std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> cols(cols_);
    std::iota(cols.begin(), cols.end(), std::size_t{0});
    std::vector<double> result(cols_, 0.0);
    std::transform(cols.begin(), cols.end(), result.begin(),
                   [this](std::size_t c) {
                       return std::accumulate(
                           this->data_.begin(),
                           this->data_.end() - (cols_ - c) % cols_,
                           0.0,
                           [c, this](double s, double v) { return s + v; });
                   });
    return result;
}

